var a=[{title:`Vad som räknas som HIIT`,text:`HIIT kräver arbete som är hårt för din nuvarande kondition, oftast följt av ett lättare intervall som låter dig göra en ny bra insats. Tung andning är väntat, men att tappa kontrollen över tekniken är det inte. Att rusa genom cirklar ger inte automatiskt samma träningseffekt som strukturerade högintensiva aeroba intervaller.`},{title:`Vad Tabata är`,text:`Det klassiska Tabata-formatet är åtta omgångar med 20 sekunders hårt arbete och 10 sekunders vila, fyra minuter totalt. Den ursprungliga forskningen använde mycket intensiva cykelinsatser, så en vardaglig 20/10-cirkel kallas bättre ”Tabata-liknande” om inte ansträngningen är likartad. Ett kort protokoll kräver ändå uppvärmning före och återhämtning efteråt.`},{title:`Vem bör börja enklare`,text:`Om du kommer tillbaka efter ett uppehåll från aktivitet eller lär dig nya rörelser kan några veckor med bekväm aerob träning först passa dig bättre. Om du har ett medicinskt tillstånd som kan påverkas, fråga din läkare innan du börjar. Burpees och hopp behövs inte för att göra konditionsträning intensiv, och en motionscykel kan vara säkrare och lättare att kontrollera.`},{title:`Begränsa det hårda arbetet`,text:`Börja med korta intervaller som du kan genomföra med bra form och lämna tillräckligt med lätta dagar mellan hårda pass. Att höja frekvens, intensitet och antal omgångar samtidigt kan ge trötthet utan extra nytta. HIIT är ett alternativ vid sidan av jämn aktivitet, styrketräning och vardagspromenader, och du kan bli vältränad utan det.`}];var r=[{label:`ACE: utforma högintensiva intervaller`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`ACE: det ursprungliga Tabata-intervallformatet`,url:`https://www.acefitness.org/continuing-education/prosource/hiit-special-issue/3743/is-tabata-all-it-s-cracked-up-to-be/`},{label:`CDC: rekommendationer om fysisk aktivitet för vuxna`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var n={sections:a,sources:r};export{n as default,a as sections,r as sources};